reference_solution:
def run_length_encode(text):
    if not text: return ""
    parts, start = [], 0
    for i in range(1, len(text) + 1):
        if i == len(text) or text[i] != text[start]:
            parts.append(text[start] + str(i - start)); start = i
    return "".join(parts)

